## 1. Compreensão do problema

O objetivo é calcular, para cada interseção inicial `i`, o maior tamanho de uma sequência de interseções adjacentes em que as posições ímpares formam uma sequência estritamente crescente e as posições pares também.

A entrada contém um grafo não direcionado com `N` vértices e `M` arestas. A saída deve conter `N` inteiros: a resposta para cada vértice. Os limites são `N ≤ 10^5` e `M ≤ 5 × 10^5`.

A sequência pode repetir um vértice em posições de paridades diferentes; o que não pode se repetir é um vértice na mesma subsequência de posições ímpares ou pares. Como cada uma dessas subsequências é estritamente crescente, o tamanho de uma resposta é no máximo `2N`.

Se um vértice não tem vizinhos, a resposta para ele é `1`.

## 2. Planejamento e design algorítmico

Considere um estado `(a, b)`, representando uma sequência que começa com `a, b`. Para acrescentar o próximo vértice `c`, é necessário que:

- `b` e `c` sejam vizinhos;
- `c > a`, pois `c` ocupa a mesma paridade que `a`.

Definimos `dp[a][b]` como o maior tamanho de uma sequência começando por `a, b`. Então:

`dp[a][b] = max(2, 1 + max(dp[b][c]))`, considerando vizinhos `c` de `b` com `c > a`.

Essa recorrência forma um DAG: qualquer dependência de `(a, b)` aponta para `(b, c)` com `c > a`, logo `b + c > a + b`. Podemos, portanto, calcular os estados em ordem decrescente da soma dos extremos.

Para cada vértice `b`, precisamos consultar o maior `dp[b][c]` entre seus vizinhos `c > a`. Mantemos os vizinhos ordenados e usamos uma Fenwick Tree de máximo para responder a consultas de sufixo. Cada estado é processado em `O(log M)`.

A resposta de um vértice `a` é o máximo de `dp[a][b]` entre seus vizinhos `b`, ou `1` se não houver vizinhos.

**Complexidade:** `O((N + M) log M)` em tempo e `O(N + M)` em memória.

## 3. Codificação em C

```c
#include <stdio.h>
#include <stdlib.h>

static int comparar_ints(const void *a, const void *b) {
    int x = *(const int *)a;
    int y = *(const int *)b;
    return (x > y) - (x < y);
}

int main(void) {
    int N, M;

    if (scanf("%d %d", &N, &M) != 2) {
        return 0;
    }

    int *A = (int *)malloc((size_t)(M > 0 ? M : 1) * sizeof(int));
    int *B = (int *)malloc((size_t)(M > 0 ? M : 1) * sizeof(int));
    int *grau = (int *)calloc((size_t)N + 1, sizeof(int));

    if (A == NULL || B == NULL || grau == NULL) {
        free(A);
        free(B);
        free(grau);
        return 0;
    }

    for (int i = 0; i < M; i++) {
        scanf("%d %d", &A[i], &B[i]);
        grau[A[i]]++;
        grau[B[i]]++;
    }

    int total = 2 * M;

    int *inicio = (int *)malloc(((size_t)N + 2) * sizeof(int));
    int *proximo = (int *)malloc(((size_t)N + 1) * sizeof(int));
    int *vizinho = (int *)malloc((size_t)(total > 0 ? total : 1) * sizeof(int));
    int *origem = (int *)malloc((size_t)(total > 0 ? total : 1) * sizeof(int));
    int *cursor = (int *)malloc(((size_t)N + 1) * sizeof(int));

    if (inicio == NULL || proximo == NULL || vizinho == NULL ||
        origem == NULL || cursor == NULL) {
        free(A);
        free(B);
        free(grau);
        free(inicio);
        free(proximo);
        free(vizinho);
        free(origem);
        free(cursor);
        return 0;
    }

    inicio[1] = 0;
    for (int u = 1; u <= N; u++) {
        inicio[u + 1] = inicio[u] + grau[u];
    }

    for (int u = 1; u <= N; u++) {
        cursor[u] = inicio[u];
    }

    for (int i = 0; i < M; i++) {
        int pos = cursor[A[i]]++;
        vizinho[pos] = B[i];
        origem[pos] = A[i];

        pos = cursor[B[i]]++;
        vizinho[pos] = A[i];
        origem[pos] = B[i];
    }

    free(A);
    free(B);
    free(cursor);

    for (int u = 1; u <= N; u++) {
        int quantidade = grau[u];
        if (quantidade > 1) {
            qsort(vizinho + inicio[u], (size_t)quantidade,
                  sizeof(int), comparar_ints);
        }
    }

    /*
     * Cada estado (u, v) é identificado pela posição do vizinho v
     * na lista de adjacência de u. Agrupamos os estados por u + v.
     */
    int max_soma = 2 * N;
    int *cabeca = (int *)malloc(((size_t)max_soma + 1) * sizeof(int));
    int *prox_estado = (int *)malloc((size_t)(total > 0 ? total : 1) * sizeof(int));
    int *dp = (int *)malloc((size_t)(total > 0 ? total : 1) * sizeof(int));
    int *resposta = (int *)malloc(((size_t)N + 1) * sizeof(int));
    int *fenwick_inicio = (int *)malloc(((size_t)N + 2) * sizeof(int));

    if (cabeca == NULL || prox_estado == NULL || dp == NULL ||
        resposta == NULL || fenwick_inicio == NULL) {
        free(grau);
        free(inicio);
        free(proximo);
        free(vizinho);
        free(origem);
        free(cabeca);
        free(prox_estado);
        free(dp);
        free(resposta);
        free(fenwick_inicio);
        return 0;
    }

    for (int s = 0; s <= max_soma; s++) {
        cabeca[s] = -1;
    }

    for (int u = 1; u <= N; u++) {
        for (int p = inicio[u]; p < inicio[u + 1]; p++) {
            int soma = u + vizinho[p];
            prox_estado[p] = cabeca[soma];
            cabeca[soma] = p;
        }
    }

    /*
     * Fenwick Tree separada para cada vértice.
     * A indexação invertida permite consultar vizinhos maiores
     * usando uma consulta de prefixo.
     */
    int tamanho_fenwick = 0;
    for (int u = 1; u <= N; u++) {
        fenwick_inicio[u] = tamanho_fenwick;
        tamanho_fenwick += grau[u] + 1;
    }

    int *fenwick = (int *)calloc((size_t)(tamanho_fenwick > 0 ? tamanho_fenwick : 1),
                                 sizeof(int));
    if (fenwick == NULL) {
        free(grau);
        free(inicio);
        free(proximo);
        free(vizinho);
        free(origem);
        free(cabeca);
        free(prox_estado);
        free(dp);
        free(resposta);
        free(fenwick_inicio);
        return 0;
    }

    for (int u = 1; u <= N; u++) {
        resposta[u] = 1;
    }

    for (int soma = max_soma; soma >= 2; soma--) {
        for (int p = cabeca[soma]; p != -1; p = prox_estado[p]) {
            int a = origem[p];
            int b = vizinho[p];

            /* Encontra os vizinhos de b que são maiores que a. */
            int esquerda = inicio[b];
            int direita = inicio[b + 1];
            while (esquerda < direita) {
                int meio = esquerda + (direita - esquerda) / 2;
                if (vizinho[meio] <= a) {
                    esquerda = meio + 1;
                } else {
                    direita = meio;
                }
            }

            int quantidade_maiores = inicio[b + 1] - esquerda;
            int base_b = fenwick_inicio[b];
            int melhor = 0;

            /* Consulta o máximo dp[b][c] para c > a. */
            int indice = quantidade_maiores;
            while (indice > 0) {
                int valor = fenwick[base_b + indice];
                if (valor > melhor) {
                    melhor = valor;
                }
                indice -= indice & -indice;
            }

            dp[p] = (melhor > 0) ? melhor + 1 : 2;

            if (dp[p] > resposta[a]) {
                resposta[a] = dp[p];
            }

            /* Registra dp[a][b] na Fenwick Tree de a. */
            int posicao_na_lista = p - inicio[a];
            int indice_invertido = grau[a] - posicao_na_lista;
            int base_a = fenwick_inicio[a];

            while (indice_invertido <= grau[a]) {
                if (dp[p] > fenwick[base_a + indice_invertido]) {
                    fenwick[base_a + indice_invertido] = dp[p];
                }
                indice_invertido += indice_invertido & -indice_invertido;
            }
        }
    }

    for (int u = 1; u <= N; u++) {
        if (u > 1) {
            putchar(' ');
        }
        printf("%d", resposta[u]);
    }
    putchar('\n');

    free(grau);
    free(inicio);
    free(proximo);
    free(vizinho);
    free(origem);
    free(cabeca);
    free(prox_estado);
    free(dp);
    free(resposta);
    free(fenwick_inicio);
    free(fenwick);

    return 0;
}
```

## 4. Retrospecto e verificação

A recorrência respeita as duas condições de crescimento: ao acrescentar `c` depois de `a, b`, verificamos `c > a`; o estado seguinte fará a verificação equivalente para a outra paridade.

Como toda dependência passa de uma soma `a + b` para uma soma maior `b + c`, os estados necessários já foram calculados quando cada consulta é feita.

Para `N = 1` ou para vértices isolados, nenhuma transição é possível e a resposta permanece `1`. O caso `M = 0` também é coberto. Os exemplos seguem a mesma recorrência: em particular, sequências maiores que `N` podem ocorrer porque um vértice pode aparecer uma vez em cada paridade.

